"""Interface-only adapter around the exact historical Git source bytes."""
import base64 as _base64
import hashlib as _hashlib
from pathlib import Path as _Path
_RAW = _base64.b64decode('')
assert _hashlib.sha256(_RAW).hexdigest() == 'c8021924dc9649c70e1f60a92ad1efefeab3b5f1e89042487fe870ed141c188a'
exec(compile(_RAW, __file__ + ':historical-v0.5.1', 'exec'), globals())
ROOT = _Path('.')
OUT = _Path('.')

def run(num):
    model = reconstruct(ROOT / 'LiDAR_xyz' / (str(num) + '.xyz'),
                        OUT / (str(num) + '_lod2.obj'),
                        ground_z=None, noise_mode='conservative')
    return model, None, None
